package service

import (
	"net/http/httptest"
	"os"
	"testing"
	"time"

	"github.com/QuantumNous/new-api/common"
	"github.com/QuantumNous/new-api/model"
	"github.com/QuantumNous/new-api/pkg/billingexpr"
	relaycommon "github.com/QuantumNous/new-api/relay/common"
	"github.com/QuantumNous/new-api/relaykit/dto"
	"github.com/gin-gonic/gin"
	"github.com/stretchr/testify/require"
)

const auditInitial = 10000000

type backendAuditResult struct {
	Name             string
	ExpectedQuota    int
	ActualQuota      int
	PreConsumed      int
	WalletDebit      int
	TokenDebit       int
	TokenUsed        int
	UserUsed         int
	ChannelUsed      int
	RequestCount     int
	InputTokens      int
	CacheWriteTokens int
	Params           billingexpr.TokenParams
	MatchedTier      string
}

func auditSetup(t *testing.T, expr string, group float64, pre int) (*gin.Context, *relaycommon.RelayInfo) {
	t.Helper()
	truncate(t)
	gin.SetMode(gin.TestMode)
	seedUser(t, 98101, auditInitial)
	seedToken(t, 98102, 98101, "local-audit-token", auditInitial)
	seedChannel(t, 98103)
	c, _ := gin.CreateTestContext(httptest.NewRecorder())
	c.Request = httptest.NewRequest("POST", "/v1/chat/completions", nil)
	c.Set(common.RequestIdKey, t.Name())
	c.Set("token_name", "local-audit-token")
	info := &relaycommon.RelayInfo{
		UserId: 98101, TokenId: 98102, TokenKey: "local-audit-token", UserQuota: auditInitial,
		ChannelMeta:     &relaycommon.ChannelMeta{ChannelId: 98103, UpstreamModelName: "local-billing-audit"},
		OriginModelName: "local-billing-audit", RequestId: t.Name(),
		UserGroup: "default", UsingGroup: "default", ForcePreConsume: true,
		StartTime: time.Now(), FirstResponseTime: time.Now(), TieredBillingSnapshot: makeSnapshot(expr, group, 0, 0),
	}
	info.TieredBillingSnapshot.EstimatedQuotaAfterGroup = pre
	info.PriceData.ModelRatio = 1
	info.PriceData.CompletionRatio = 1
	info.PriceData.GroupRatioInfo.GroupRatio = group
	require.Nil(t, PreConsumeBilling(c, pre, info))
	var user model.User
	var token model.Token
	require.NoError(t, model.DB.First(&user, 98101).Error)
	require.NoError(t, model.DB.First(&token, 98102).Error)
	require.Equal(t, auditInitial-pre, user.Quota, "wallet pre-consume")
	require.Equal(t, auditInitial-pre, token.RemainQuota, "token pre-consume")
	return c, info
}

func auditRead(t *testing.T, expected, pre int) backendAuditResult {
	t.Helper()
	var user model.User
	var token model.Token
	var channel model.Channel
	var logs []model.Log
	require.NoError(t, model.DB.First(&user, 98101).Error)
	require.NoError(t, model.DB.First(&token, 98102).Error)
	require.NoError(t, model.DB.First(&channel, 98103).Error)
	require.NoError(t, model.DB.Where("user_id = ? AND type = ?", 98101, model.LogTypeConsume).Find(&logs).Error)
	require.Len(t, logs, 1)
	log := logs[0]
	r := backendAuditResult{Name: t.Name(), ExpectedQuota: expected, ActualQuota: log.Quota, PreConsumed: pre,
		WalletDebit: auditInitial - user.Quota, TokenDebit: auditInitial - token.RemainQuota, TokenUsed: token.UsedQuota,
		UserUsed: user.UsedQuota, ChannelUsed: int(channel.UsedQuota), RequestCount: user.RequestCount,
		InputTokens: log.InputTokens, CacheWriteTokens: log.CacheWriteTokens}
	require.Equal(t, r.ActualQuota, r.WalletDebit, "log vs wallet")
	require.Equal(t, r.ActualQuota, r.TokenDebit, "log vs token")
	require.Equal(t, r.ActualQuota, r.TokenUsed, "log vs token used")
	require.Equal(t, r.ActualQuota, r.UserUsed, "log vs user used")
	require.Equal(t, r.ActualQuota, r.ChannelUsed, "log vs channel used")
	require.Equal(t, 1, r.RequestCount)
	return r
}

func auditOpenAI(p, c, cr int) *dto.Usage {
	u := &dto.Usage{PromptTokens: p, CompletionTokens: c, TotalTokens: p + c}
	u.PromptTokensDetails.CachedTokens = cr
	u.BillingUsage = dto.NewOpenAIChatBillingUsage(u)
	return u
}

func auditClaude(p, c, cr, cc5m, cc1h int, split bool) *dto.Usage {
	raw := &dto.ClaudeUsage{InputTokens: p, OutputTokens: c, CacheReadInputTokens: cr, CacheCreationInputTokens: cc5m + cc1h}
	if split {
		raw.CacheCreation = &dto.ClaudeCacheCreationUsage{Ephemeral5mInputTokens: cc5m, Ephemeral1hInputTokens: cc1h}
	}
	return &dto.Usage{PromptTokens: p, CompletionTokens: c, TotalTokens: p + c, UsageSemantic: "anthropic", BillingUsage: dto.NewClaudeMessagesBillingUsage(raw)}
}

func TestBackendChainAudit(t *testing.T) {
	var results []backendAuditResult
	defer func() {
		out, err := common.Marshal(results)
		require.NoError(t, err)
		require.NoError(t, os.WriteFile("/tmp/apimeter-expr-audit-20261110/backend-chain-results.json", out, 0600))
	}()
	four := `tier("base", p*0.1234+c*0.5678+cr*0.0123)`
	flat := `tier("base", p*3+c*15)`
	cache := `tier("base", p*3+c*15+cr*0.3+cc*3.75+cc1h*6)`
	haiku := `len <= 100000 ? tier("standard", p*0.1+c*0.5+cr*0.01+cc*0.125+cc1h*0.2) : tier("long_context", p*0.5+c*2.5+cr*0.05+cc*0.625+cc1h*1)`
	cases := []struct {
		name, expr    string
		usage         *dto.Usage
		group         float64
		pre, expected int
	}{
		{"openai_four_decimal_refund", four, auditOpenAI(1000000, 100000, 200000), 1, 100000, 78980},
		{"openai_four_decimal_supplement", four, auditOpenAI(1000000, 100000, 200000), 1, 1000, 78980},
		{"openai_group_rounding", four, auditOpenAI(1000000, 100000, 200000), 0.37, 100000, 29223},
		{"openai_free_group", four, auditOpenAI(1000000, 100000, 200000), 0, 100000, 0},
		{"openai_no_separate_cache", flat, auditOpenAI(1000, 500, 200), 1, 10000, 5250},
		{"claude_explicit_cache_split", cache, auditClaude(8000, 5000, 2000, 3000, 1000, true), 1, 100000, 58425},
		{"claude_split_long_context", haiku, auditClaude(90000, 1000, 0, 20000, 0, true), 1, 100000, 30000},
		{"claude_missing_split_long_context", haiku, auditClaude(90000, 1000, 0, 20000, 0, false), 1, 100000, 30000},
		{"claude_missing_split_flat", cache, auditClaude(1000, 500, 0, 3000, 0, false), 1, 100000, 10875},
		{"claude_fable_live_missing_split", `tier("base", p*10+c*50+cr*0.25+cc*12.5+cc1h*20)`, auditClaude(1000, 500, 0, 3000, 0, false), 1, 100000, 36250},
		{"claude_no_separate_cache", flat, auditClaude(800, 500, 200, 0, 0, true), 1, 10000, 5250},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c, info := auditSetup(t, tc.expr, tc.group, tc.pre)
			params := BuildTieredTokenParams(effectiveBillingUsage(tc.usage), tc.usage.UsageSemantic == "anthropic", billingexpr.UsedVars(tc.expr))
			_, _, tr := TryTieredSettle(info, params)
			require.NotNil(t, tr)
			PostTextConsumeQuota(c, info, tc.usage, nil)
			r := auditRead(t, tc.expected, tc.pre)
			r.Params = params
			r.MatchedTier = tr.MatchedTier
			results = append(results, r)
			// Repeating settlement must not adjust balances a second time.
			require.NoError(t, SettleBilling(c, info, r.ActualQuota))
			require.Equal(t, r.WalletDebit, auditRead(t, tc.expected, tc.pre).WalletDebit)
			require.Equal(t, tc.expected, r.ActualQuota, "independently calculated expected charge")
		})
	}
	for _, tc := range []struct {
		name, expr string
		expected   int
	}{
		{"realtime_text_fallback", `tier("base", p*2+c*10)`, 3500},
		{"realtime_audio_separate", `tier("base", p*2+c*10+ai*20+ao*40)`, 16700},
		{"realtime_audio_only", `tier("base", ai*20+ao*40)`, 16000},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c, info := auditSetup(t, tc.expr, 1, 100000)
			u := &dto.RealtimeUsage{InputTokens: 1000, OutputTokens: 500, TotalTokens: 1500}
			u.InputTokenDetails.TextTokens = 200
			u.InputTokenDetails.AudioTokens = 800
			u.OutputTokenDetails.TextTokens = 100
			u.OutputTokenDetails.AudioTokens = 400
			PostWssConsumeQuota(c, info, info.OriginModelName, u, "")
			r := auditRead(t, tc.expected, 100000)
			results = append(results, r)
			require.Equal(t, tc.expected, r.ActualQuota, "independently calculated expected charge")
		})
	}
}

func TestBackendFundingLifecycleAudit(t *testing.T) {
	for _, source := range []string{"wallet", "subscription"} {
		for _, actual := range []int{0, 500, 1000, 2000} {
			t.Run(source+"_"+common.GetJsonString(actual), func(t *testing.T) {
				c, info := auditSetup(t, `tier("base", p)`, 1, 1000)
				session := info.Billing.(*BillingSession)
				if source == "subscription" {
					// Revert the setup wallet reservation before creating a subscription session.
					require.NoError(t, session.Settle(0))
					require.NoError(t, model.DB.Create(&model.SubscriptionPlan{Id: 98105, Title: "Audit plan", DurationUnit: model.SubscriptionDurationMonth, DurationValue: 1, TotalAmount: auditInitial, Enabled: true}).Error)
					seedSubscription(t, 98104, 98101, auditInitial, 0)
					require.NoError(t, model.DB.Model(&model.UserSubscription{}).Where("id = ?", 98104).Update("plan_id", 98105).Error)
					info.TokenUserSubscriptionId = 98104
					info.BillingSource = BillingSourceSubscription
					require.NoError(t, model.DB.Model(&model.Token{}).Where("id = ?", 98102).Updates(map[string]any{"billing_source": BillingSourceSubscription, "user_subscription_id": 98104}).Error)
					if apiErr := PreConsumeBilling(c, 1000, info); apiErr != nil {
						t.Fatal(apiErr.Error())
					}
					session = info.Billing.(*BillingSession)
				}
				require.NoError(t, session.Settle(actual))
				require.NoError(t, session.Settle(actual))
				session.Refund(c) // A completed settlement must not be refunded.
				var user model.User
				var token model.Token
				require.NoError(t, model.DB.First(&user, 98101).Error)
				require.NoError(t, model.DB.First(&token, 98102).Error)
				require.Equal(t, actual, auditInitial-token.RemainQuota)
				require.Equal(t, actual, token.UsedQuota)
				if source == "wallet" {
					require.Equal(t, actual, auditInitial-user.Quota)
				} else {
					var sub model.UserSubscription
					require.NoError(t, model.DB.First(&sub, 98104).Error)
					require.Equal(t, int64(actual), sub.AmountUsed)
					require.Equal(t, auditInitial, user.Quota)
				}
			})
		}
	}
}

func TestBackendRealtimeStreamingAudit(t *testing.T) {
	var results []map[string]any
	defer func() {
		out, err := common.Marshal(results)
		require.NoError(t, err)
		require.NoError(t, os.WriteFile("/tmp/apimeter-expr-audit-20261110/backend-realtime-streaming-results.json", out, 0600))
	}()
	for _, mode := range []string{"tiered_expr", "ratio"} {
		for _, chunks := range []int{1, 2} {
			t.Run(mode+"_chunks_"+common.GetJsonString(chunks), func(t *testing.T) {
				setupRealtimeBillingRatioSettings(t)
				c, info := auditSetup(t, `tier("base", p*2)`, 1, 1000)
				info.OriginModelName = "realtime-agent-test"
				if mode == "ratio" {
					info.TieredBillingSnapshot = nil
				}
				chunk := &dto.RealtimeUsage{InputTokens: 100, TotalTokens: 100}
				chunk.InputTokenDetails.TextTokens = 100
				for i := 0; i < chunks; i++ {
					require.NoError(t, PreWssConsumeQuota(c, info, chunk))
				}
				total := &dto.RealtimeUsage{InputTokens: 100 * chunks, TotalTokens: 100 * chunks}
				total.InputTokenDetails.TextTokens = 100 * chunks
				PostWssConsumeQuota(c, info, info.OriginModelName, total, "")
				var user model.User
				var token model.Token
				var log model.Log
				var channel model.Channel
				require.NoError(t, model.DB.First(&user, 98101).Error)
				require.NoError(t, model.DB.First(&token, 98102).Error)
				require.NoError(t, model.DB.First(&channel, 98103).Error)
				require.NoError(t, model.DB.Where("user_id = ? AND type = ?", 98101, model.LogTypeConsume).First(&log).Error)
				results = append(results, map[string]any{"name": t.Name(), "mode": mode, "chunks": chunks, "initial_preconsume": 1000, "session_preconsume_after_chunks": info.Billing.GetPreConsumedQuota(), "expected_quota": 100 * chunks, "log_quota": log.Quota, "wallet_debit": auditInitial - user.Quota, "token_debit": auditInitial - token.RemainQuota, "token_used": token.UsedQuota, "user_used": user.UsedQuota, "channel_used": channel.UsedQuota})
				require.Equal(t, 100*chunks, log.Quota)
				require.Equal(t, log.Quota, auditInitial-user.Quota, "streaming charges must be reconciled at final settlement")
			})
		}
	}
}
